-- VITALORA AI - Initial relational schema (Turso / libSQL / SQLite 3.47)
-- Conventions:
--   * All IDs are UUIDv4 strings generated by the application layer.
--   * All timestamps are ISO-8601 UTC strings ('YYYY-MM-DDTHH:MM:SS.sssZ').
--   * JSON columns are TEXT containing serialized JSON (SQLite convention),
--     validated at the application boundary by Pydantic schemas.
--   * Tenant isolation: every tenant-owned table carries organization_id and
--     every repository query MUST filter by it.

-- ── Migration bookkeeping ─────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS migrations (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    filename    TEXT NOT NULL UNIQUE,
    applied_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- ── Tenancy & identity ────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS organizations (
    id            TEXT PRIMARY KEY,
    name          TEXT NOT NULL,
    slug          TEXT NOT NULL UNIQUE,
    plan          TEXT NOT NULL DEFAULT 'trial',
    status        TEXT NOT NULL DEFAULT 'active',
    created_at    TEXT NOT NULL,
    updated_at    TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS users (
    id               TEXT PRIMARY KEY,
    organization_id  TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    email            TEXT NOT NULL,
    password_hash    TEXT NOT NULL,
    name             TEXT NOT NULL,
    role             TEXT NOT NULL CHECK (role IN ('owner','org_admin','clinic_admin','staff','analyst')),
    status           TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','disabled')),
    email_verified   INTEGER NOT NULL DEFAULT 0,
    last_login_at    TEXT,
    created_at       TEXT NOT NULL,
    updated_at       TEXT NOT NULL,
    UNIQUE (organization_id, email)
);
CREATE INDEX IF NOT EXISTS idx_users_org ON users(organization_id);

CREATE TABLE IF NOT EXISTS refresh_sessions (
    id             TEXT PRIMARY KEY,
    user_id        TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash     TEXT NOT NULL UNIQUE,
    user_agent     TEXT,
    expires_at     TEXT NOT NULL,
    revoked_at     TEXT,
    created_at     TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_refresh_sessions_user ON refresh_sessions(user_id);

-- ── Clinics & scheduling configuration ────────────────────────────────────
CREATE TABLE IF NOT EXISTS clinics (
    id             TEXT PRIMARY KEY,
    organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    name           TEXT NOT NULL,
    slug           TEXT NOT NULL,
    timezone       TEXT NOT NULL DEFAULT 'UTC',
    address        TEXT,
    phone          TEXT,
    email          TEXT,
    status         TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
    created_at     TEXT NOT NULL,
    updated_at     TEXT NOT NULL,
    UNIQUE (organization_id, slug)
);
CREATE INDEX IF NOT EXISTS idx_clinics_org ON clinics(organization_id);

CREATE TABLE IF NOT EXISTS clinic_hours (
    id              TEXT PRIMARY KEY,
    organization_id TEXT NOT NULL,
    clinic_id       TEXT NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
    day_of_week     INTEGER NOT NULL CHECK (day_of_week BETWEEN 0 AND 6),
    open_time       TEXT NOT NULL DEFAULT '09:00',
    close_time      TEXT NOT NULL DEFAULT '17:00',
    is_closed       INTEGER NOT NULL DEFAULT 0,
    UNIQUE (clinic_id, day_of_week)
);

CREATE TABLE IF NOT EXISTS schedule_exceptions (
    id              TEXT PRIMARY KEY,
    organization_id TEXT NOT NULL,
    clinic_id       TEXT NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
    date            TEXT NOT NULL,
    is_closed       INTEGER NOT NULL DEFAULT 1,
    open_time       TEXT,
    close_time      TEXT,
    reason          TEXT,
    UNIQUE (clinic_id, date)
);

-- ── Clinical staff & services ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS providers (
    id              TEXT PRIMARY KEY,
    organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    clinic_id       TEXT NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
    name            TEXT NOT NULL,
    specialty       TEXT,
    email           TEXT,
    phone           TEXT,
    status          TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
    created_at      TEXT NOT NULL,
    updated_at      TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_providers_org ON providers(organization_id);
CREATE INDEX IF NOT EXISTS idx_providers_clinic ON providers(clinic_id);

CREATE TABLE IF NOT EXISTS provider_time_off (
    id              TEXT PRIMARY KEY,
    organization_id TEXT NOT NULL,
    provider_id     TEXT NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
    starts_at       TEXT NOT NULL,
    ends_at         TEXT NOT NULL,
    reason          TEXT
);

CREATE TABLE IF NOT EXISTS services (
    id               TEXT PRIMARY KEY,
    organization_id  TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    clinic_id        TEXT NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
    name             TEXT NOT NULL,
    description      TEXT,
    duration_minutes INTEGER NOT NULL DEFAULT 30 CHECK (duration_minutes BETWEEN 5 AND 480),
    price_display    TEXT,
    is_active        INTEGER NOT NULL DEFAULT 1,
    created_at       TEXT NOT NULL,
    updated_at       TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_services_org ON services(organization_id);
CREATE INDEX IF NOT EXISTS idx_services_clinic ON services(clinic_id);

-- ── AI receptionists ──────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS receptionists (
    id                 TEXT PRIMARY KEY,
    organization_id    TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    clinic_id          TEXT NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
    name               TEXT NOT NULL,
    persona            TEXT,
    status             TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','active','paused')),
    languages          TEXT NOT NULL DEFAULT '["en"]',
    primary_language   TEXT NOT NULL DEFAULT 'en',
    voice_provider     TEXT NOT NULL DEFAULT 'zai',
    voice_id           TEXT NOT NULL DEFAULT 'tongtong',
    speaking_speed     REAL NOT NULL DEFAULT 1.0 CHECK (speaking_speed BETWEEN 0.5 AND 2.0),
    greeting_message   TEXT,
    system_prompt_extra TEXT,
    capabilities       TEXT NOT NULL DEFAULT '{"booking":true,"knowledge_qa":true,"callback_requests":true}',
    escalation         TEXT NOT NULL DEFAULT '{}',
    created_by         TEXT REFERENCES users(id) ON DELETE SET NULL,
    created_at         TEXT NOT NULL,
    updated_at         TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_receptionists_org ON receptionists(organization_id);
CREATE INDEX IF NOT EXISTS idx_receptionists_clinic ON receptionists(clinic_id);

-- ── Appointments ──────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS appointments (
    id                  TEXT PRIMARY KEY,
    organization_id     TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    clinic_id           TEXT NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
    provider_id         TEXT NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
    service_id          TEXT NOT NULL REFERENCES services(id) ON DELETE CASCADE,
    receptionist_id     TEXT REFERENCES receptionists(id) ON DELETE SET NULL,
    patient_name        TEXT NOT NULL,
    patient_phone       TEXT,
    patient_email       TEXT,
    patient_notes       TEXT,
    starts_at           TEXT NOT NULL,
    ends_at             TEXT NOT NULL,
    duration_minutes    INTEGER NOT NULL,
    status              TEXT NOT NULL DEFAULT 'booked'
                        CHECK (status IN ('booked','confirmed','cancelled','completed','no_show','rescheduled')),
    cancellation_reason TEXT,
    source              TEXT NOT NULL DEFAULT 'web' CHECK (source IN ('web','voice','api')),
    idempotency_key     TEXT,
    created_by          TEXT,
    created_at          TEXT NOT NULL,
    updated_at          TEXT NOT NULL
);
-- Conflict prevention: one active appointment per provider per start time.
CREATE UNIQUE INDEX IF NOT EXISTS uq_appointments_provider_slot
    ON appointments(provider_id, starts_at)
    WHERE status IN ('booked','confirmed');
-- Idempotent booking: safe retries never create duplicates.
CREATE UNIQUE INDEX IF NOT EXISTS uq_appointments_idempotency
    ON appointments(organization_id, idempotency_key)
    WHERE idempotency_key IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_appointments_org_start ON appointments(organization_id, starts_at);
CREATE INDEX IF NOT EXISTS idx_appointments_clinic_start ON appointments(clinic_id, starts_at);
CREATE INDEX IF NOT EXISTS idx_appointments_phone ON appointments(patient_phone);

-- ── Voice conversations ───────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS conversation_sessions (
    id               TEXT PRIMARY KEY,
    organization_id  TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    clinic_id        TEXT NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
    receptionist_id  TEXT NOT NULL REFERENCES receptionists(id) ON DELETE CASCADE,
    channel          TEXT NOT NULL DEFAULT 'browser' CHECK (channel IN ('browser','phone','api')),
    language         TEXT NOT NULL DEFAULT 'en',
    status           TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','completed','failed','escalated')),
    outcome          TEXT CHECK (outcome IN (NULL,'appointment_booked','appointment_cancelled','appointment_rescheduled','callback_requested','transferred_to_human','info_provided','unresolved')),
    end_reason       TEXT,
    started_at       TEXT NOT NULL,
    ended_at         TEXT,
    duration_seconds INTEGER,
    caller_ref       TEXT,
    created_at       TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_sessions_org_start ON conversation_sessions(organization_id, started_at);
CREATE INDEX IF NOT EXISTS idx_sessions_receptionist ON conversation_sessions(receptionist_id);

CREATE TABLE IF NOT EXISTS conversation_messages (
    id              TEXT PRIMARY KEY,
    session_id      TEXT NOT NULL REFERENCES conversation_sessions(id) ON DELETE CASCADE,
    organization_id TEXT NOT NULL,
    role            TEXT NOT NULL CHECK (role IN ('user','assistant','system','tool')),
    content         TEXT,
    tool_name       TEXT,
    tool_payload    TEXT,
    latency_ms      INTEGER,
    created_at      TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_messages_session ON conversation_messages(session_id, created_at);

-- ── Knowledge base (RAG) ──────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS knowledge_documents (
    id              TEXT PRIMARY KEY,
    organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    clinic_id       TEXT REFERENCES clinics(id) ON DELETE CASCADE,
    title           TEXT NOT NULL,
    source_type     TEXT NOT NULL DEFAULT 'manual' CHECK (source_type IN ('manual','faq','document','url')),
    content_text    TEXT NOT NULL DEFAULT '',
    status          TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','processing','indexed','failed','inactive')),
    chunk_count     INTEGER NOT NULL DEFAULT 0,
    error           TEXT,
    uploaded_by     TEXT REFERENCES users(id) ON DELETE SET NULL,
    created_at      TEXT NOT NULL,
    updated_at      TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_knowledge_docs_org ON knowledge_documents(organization_id);

CREATE TABLE IF NOT EXISTS knowledge_chunks (
    id              TEXT PRIMARY KEY,
    organization_id TEXT NOT NULL,
    document_id     TEXT NOT NULL REFERENCES knowledge_documents(id) ON DELETE CASCADE,
    chunk_index     INTEGER NOT NULL,
    content         TEXT NOT NULL,
    created_at      TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_chunks_document ON knowledge_chunks(document_id);

-- FTS5 full-text retrieval (verified supported by this Turso instance).
-- External-content table kept in sync by triggers; rowid maps to knowledge_chunks.rowid.
CREATE VIRTUAL TABLE IF NOT EXISTS knowledge_chunks_fts USING fts5(
    content,
    content='knowledge_chunks',
    content_rowid='rowid'
);
CREATE TRIGGER IF NOT EXISTS knowledge_chunks_ai AFTER INSERT ON knowledge_chunks BEGIN
    INSERT INTO knowledge_chunks_fts(rowid, content) VALUES (new.rowid, new.content);
END;
CREATE TRIGGER IF NOT EXISTS knowledge_chunks_ad AFTER DELETE ON knowledge_chunks BEGIN
    INSERT INTO knowledge_chunks_fts(knowledge_chunks_fts, rowid, content)
    VALUES ('delete', old.rowid, old.content);
END;
CREATE TRIGGER IF NOT EXISTS knowledge_chunks_au AFTER UPDATE ON knowledge_chunks BEGIN
    INSERT INTO knowledge_chunks_fts(knowledge_chunks_fts, rowid, content)
    VALUES ('delete', old.rowid, old.content);
    INSERT INTO knowledge_chunks_fts(rowid, content) VALUES (new.rowid, new.content);
END;

-- ── Escalations & callbacks ───────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS escalations (
    id              TEXT PRIMARY KEY,
    organization_id TEXT NOT NULL,
    session_id      TEXT REFERENCES conversation_sessions(id) ON DELETE SET NULL,
    reason          TEXT NOT NULL,
    contact_method  TEXT NOT NULL DEFAULT 'callback' CHECK (contact_method IN ('transfer','callback','emergency')),
    status          TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','resolved')),
    details         TEXT,
    created_at      TEXT NOT NULL,
    resolved_at     TEXT
);

CREATE TABLE IF NOT EXISTS callback_requests (
    id              TEXT PRIMARY KEY,
    organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    clinic_id       TEXT REFERENCES clinics(id) ON DELETE CASCADE,
    session_id      TEXT REFERENCES conversation_sessions(id) ON DELETE SET NULL,
    patient_name    TEXT NOT NULL,
    patient_phone   TEXT NOT NULL,
    reason          TEXT,
    priority        TEXT NOT NULL DEFAULT 'normal' CHECK (priority IN ('low','normal','high','urgent')),
    status          TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','assigned','completed','cancelled')),
    created_at      TEXT NOT NULL,
    completed_at    TEXT
);
CREATE INDEX IF NOT EXISTS idx_callbacks_org ON callback_requests(organization_id, status);

-- ── Provider configuration (per organization, non-secret) ─────────────────
CREATE TABLE IF NOT EXISTS provider_configs (
    id              TEXT PRIMARY KEY,
    organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    provider_type   TEXT NOT NULL CHECK (provider_type IN ('llm','stt','tts')),
    provider_name   TEXT NOT NULL,
    model           TEXT,
    config          TEXT NOT NULL DEFAULT '{}',
    is_default      INTEGER NOT NULL DEFAULT 0,
    created_at      TEXT NOT NULL,
    updated_at      TEXT NOT NULL,
    UNIQUE (organization_id, provider_type)
);

-- ── Usage metering ────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS usage_records (
    id              TEXT PRIMARY KEY,
    organization_id TEXT NOT NULL,
    session_id      TEXT REFERENCES conversation_sessions(id) ON DELETE SET NULL,
    kind            TEXT NOT NULL CHECK (kind IN ('llm_tokens','llm_requests','stt_seconds','tts_chars')),
    provider        TEXT NOT NULL,
    quantity        REAL NOT NULL DEFAULT 0,
    meta            TEXT,
    created_at      TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_usage_org_time ON usage_records(organization_id, created_at);

-- ── Audit trail ───────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS audit_events (
    id              TEXT PRIMARY KEY,
    organization_id TEXT NOT NULL,
    actor_user_id   TEXT REFERENCES users(id) ON DELETE SET NULL,
    actor_type      TEXT NOT NULL DEFAULT 'user' CHECK (actor_type IN ('user','system','ai_receptionist')),
    actor_display   TEXT,
    action          TEXT NOT NULL,
    entity_type     TEXT,
    entity_id       TEXT,
    details         TEXT,
    ip_hash         TEXT,
    created_at      TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_audit_org_time ON audit_events(organization_id, created_at);
